/* xx_cpx_extractor.c - search raw data for CPX.
 *
 * Scans for:
 *   28 16 27 93 at +0  ("(.'.")
 *   2A 16 27 93 at +0  ("..'.")
 *   2C 16 27 93 at +0  (",.'.")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the cpx reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/cpx/xx_cpx.h"

static const uint8_t k_anchor0[] = { 0x28, 0x16, 0x27, 0x93 };
static const uint8_t k_anchor1[] = { 0x2A, 0x16, 0x27, 0x93 };
static const uint8_t k_anchor2[] = { 0x2C, 0x16, 0x27, 0x93 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
    { k_anchor1, sizeof(k_anchor1), 0U },
    { k_anchor2, sizeof(k_anchor2), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_CPX };

static Abstractformat *xx_cpx_search_open(xx_io_device *window) {
    xx_cpx *reader = xx_cpx_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_cpx_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_cpx_free((xx_cpx *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_cpx_search_open, xx_cpx_search_close
};

static xx_format_search_state *xx_cpx_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_cpx_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_cpx_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_cpx_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_cpx_extractor = {
    xx_cpx_create_format_search,
    xx_cpx_get_current_format_info,
    xx_cpx_format_search_find_next,
    xx_cpx_free_format_search
};
